                interleaveData(interleavedPoints, points, currentBatchSize, batch * batchSize);
                pointsBuffer.write(0, interleavedPoints, 0, useF16 ? roundUp(numColumns * currentBatchSize, 2) : numColumns * currentBatchSize);
