    s.uv = ivec2(0);
    s.state = 0;
    s.selected = false;
    s.valid = false;
    s.localPos = vec3(0.0);
    s.worldPos = vec3(0.0);
    s.visible = false;

    if (idx >= splat_params.y) return false;
    s.uv = ivec2(idx % splat_params.x, idx / splat_params.x);

    s.state = int(texelFetch(splatState, s.uv, 0).r * 255.0 + 0.5);
